-- Default-off exact human disclosure grants. No backfill or plaintext copy.
CREATE TABLE IF NOT EXISTS app_resource_access_grants (
 id text PRIMARY KEY, org_id text NOT NULL, owner_user_id text NOT NULL,
 recipient_user_id text NOT NULL, app_installation_id text NOT NULL,
 resource_binding_id text NOT NULL, checkpoint_id text NOT NULL, projection_id text NOT NULL,
 review_digest text NOT NULL, snapshot jsonb NOT NULL, accepted_sequence bigserial NOT NULL, accepted_at timestamptz NOT NULL,
 expires_at timestamptz NOT NULL, revoked_at timestamptz, revoked_by_user_id text,
 CONSTRAINT app_resource_access_grants_owner_fk FOREIGN KEY(org_id,resource_binding_id,owner_user_id) REFERENCES app_resource_bindings(org_id,id,owner_user_id) ON DELETE RESTRICT,
 CONSTRAINT app_resource_access_grants_checkpoint_fk FOREIGN KEY(org_id,checkpoint_id,resource_binding_id) REFERENCES app_sync_checkpoints(org_id,id,resource_binding_id) ON DELETE CASCADE,
 CONSTRAINT app_resource_access_grants_projection_fk FOREIGN KEY(org_id,projection_id) REFERENCES app_resource_projections(org_id,id) ON DELETE CASCADE,
 CONSTRAINT app_resource_access_grants_recipient_fk FOREIGN KEY(org_id,recipient_user_id) REFERENCES org_members(org_id,user_id) ON DELETE RESTRICT,
 CONSTRAINT app_resource_access_grants_review_unique UNIQUE(org_id,owner_user_id,review_digest),
 CONSTRAINT app_resource_access_grants_digest_check CHECK(review_digest ~ '^sha256:[a-f0-9]{64}$'),
 CONSTRAINT app_resource_access_grants_expiry_check CHECK(expires_at>accepted_at AND expires_at<=accepted_at+interval '24 hours'),
 CONSTRAINT app_resource_access_grants_revocation_check CHECK((revoked_at IS NULL AND revoked_by_user_id IS NULL) OR (revoked_at IS NOT NULL AND revoked_by_user_id=owner_user_id)),
 CONSTRAINT app_resource_access_grants_snapshot_check CHECK(COALESCE(jsonb_typeof(snapshot)='object' AND octet_length(snapshot::text)<=8192 AND snapshot ?& ARRAY['schema_version','purpose','org_id','owner_user_id','recipient_user_id','app_installation_id','app_version_id','grant_snapshot_id','lifecycle_epoch','grant_epoch','registration_id','operator_user_id','runtime_epoch','resource_binding_id','descriptor_digest','checkpoint_id','generation','ref','revision_digest','content_digest','field_keys','operations','app_label','recipient_label','expires_at','review_expires_at'] AND (snapshot - ARRAY['schema_version','purpose','org_id','owner_user_id','recipient_user_id','app_installation_id','app_version_id','grant_snapshot_id','lifecycle_epoch','grant_epoch','registration_id','operator_user_id','runtime_epoch','resource_binding_id','descriptor_digest','checkpoint_id','generation','ref','revision_digest','content_digest','field_keys','operations','app_label','recipient_label','expires_at','review_expires_at'])='{}'::jsonb AND snapshot->>'schema_version'='deft.app_resource_access_snapshot.v1' AND snapshot->>'purpose'='human_view' AND snapshot->>'org_id'=org_id AND snapshot->>'owner_user_id'=owner_user_id AND snapshot->>'recipient_user_id'=recipient_user_id AND snapshot->>'app_installation_id'=app_installation_id AND snapshot->>'resource_binding_id'=resource_binding_id AND snapshot->>'checkpoint_id'=checkpoint_id AND jsonb_typeof(snapshot->'ref')='object' AND jsonb_typeof(snapshot->'field_keys')='array' AND jsonb_array_length(snapshot->'field_keys') BETWEEN 1 AND 32 AND jsonb_typeof(snapshot->'operations')='array' AND jsonb_array_length(snapshot->'operations') BETWEEN 1 AND 3 AND (snapshot->'operations') <@ '["cite","read","search"]'::jsonb AND snapshot->'operations' IN ('["cite"]'::jsonb,'["read"]'::jsonb,'["search"]'::jsonb,'["cite","read"]'::jsonb,'["cite","search"]'::jsonb,'["read","search"]'::jsonb,'["cite","read","search"]'::jsonb) AND snapshot#>>'{ref,schema_version}'='deft.resource_ref.v2' AND snapshot#>>'{ref,provider,kind}'='app_runtime' AND snapshot#>>'{ref,resource_id}'=projection_id AND snapshot#>>'{ref,provider,provider_instance_id}'=snapshot->>'registration_id' AND jsonb_typeof(snapshot->'app_version_id')='string' AND jsonb_typeof(snapshot->'grant_snapshot_id')='string' AND jsonb_typeof(snapshot->'registration_id')='string' AND jsonb_typeof(snapshot->'operator_user_id')='string' AND jsonb_typeof(snapshot->'descriptor_digest')='string' AND jsonb_typeof(snapshot->'revision_digest')='string' AND jsonb_typeof(snapshot->'content_digest')='string' AND jsonb_typeof(snapshot->'expires_at')='string' AND jsonb_typeof(snapshot->'review_expires_at')='string' AND jsonb_typeof(snapshot->'app_label')='string' AND length(snapshot->>'app_label')<=200 AND jsonb_typeof(snapshot->'recipient_label')='string' AND length(snapshot->>'recipient_label')<=200 AND jsonb_typeof(snapshot->'lifecycle_epoch')='number' AND jsonb_typeof(snapshot->'grant_epoch')='number' AND jsonb_typeof(snapshot->'runtime_epoch')='number' AND jsonb_typeof(snapshot->'generation')='number',false))
);
CREATE INDEX IF NOT EXISTS app_resource_access_grants_owner_idx ON app_resource_access_grants(org_id,owner_user_id,app_installation_id);
CREATE INDEX IF NOT EXISTS app_resource_access_grants_recipient_idx ON app_resource_access_grants(org_id,recipient_user_id,accepted_sequence);
CREATE OR REPLACE FUNCTION enforce_app_resource_access_grants_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (to_jsonb(NEW)-'revoked_at'-'revoked_by_user_id') IS DISTINCT FROM (to_jsonb(OLD)-'revoked_at'-'revoked_by_user_id') OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN
  RAISE EXCEPTION 'App private access grants are immutable except one-way owner revocation';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS app_resource_access_grants_immutable_trigger ON app_resource_access_grants;
CREATE TRIGGER app_resource_access_grants_immutable_trigger BEFORE UPDATE ON app_resource_access_grants FOR EACH ROW EXECUTE FUNCTION enforce_app_resource_access_grants_immutable();
